// Валидация Telegram WebApp initData (HMAC-SHA256).
// Зеркало validator/src/initdata.py. Требует NODE_FUNCTION_ALLOW_BUILTIN=crypto
// (или вынеси проверку в validator-микросервис). При невалидной подписи бросаем
// ошибку -> выполнение прерывается, клиент получает ошибку вебхука.
const crypto = require('crypto');
const h = $json.headers || {};
const initData =
  h['x-telegram-init-data'] ||
  h['X-Telegram-Init-Data'] ||
  ($json.query && $json.query.initData) ||
  ($json.body && $json.body.initData) ||
  '';
const botToken = $env.BOT_TOKEN || '';
const maxAge = parseInt($env.INITDATA_MAX_AGE || '86400', 10);

function fail(reason) { throw new Error('initData invalid: ' + reason); }

if (!initData || !botToken) fail('empty');

const p = new URLSearchParams(initData);
const hash = p.get('hash');
if (!hash) fail('no_hash');
p.delete('hash');

const pairs = [];
for (const [k, v] of p.entries()) pairs.push([k, v]);
pairs.sort((a, b) => (a[0] < b[0] ? -1 : (a[0] > b[0] ? 1 : 0)));
const dcs = pairs.map(([k, v]) => k + '=' + v).join('\n');

const secret = crypto.createHmac('sha256', 'WebAppData').update(botToken).digest();
const calc = crypto.createHmac('sha256', secret).update(dcs).digest('hex');
if (calc !== hash) fail('bad_hash');

const authDate = parseInt(p.get('auth_date') || '0', 10);
if (!authDate) fail('no_auth_date');
if (Math.floor(Date.now() / 1000) - authDate > maxAge) fail('expired');

let user = null;
try { user = JSON.parse(p.get('user') || 'null'); } catch (e) { user = null; }
const uid = user && user.id ? user.id : null;
if (!uid) fail('no_user');

return [{ json: { user_id: uid, query: $json.query || {}, body: $json.body || {} } }];

// Строим безопасный SQL для ленты заказов из query-параметров.
// Значения экранируются; числа парсятся; лимит ограничен сверху.
const q = $json.query || {};
const uid = parseInt($json.user_id, 10);
function esc(s) { return String(s).replace(/'/g, "''"); }
function arr(csv) { return String(csv).split(',').map((s) => s.trim()).filter(Boolean); }

const where = ['1=1', "(s.status IS NULL OR s.status <> 'hidden')"];
if (q.service_type) where.push("o.service_type = '" + esc(q.service_type) + "'");
if (q.urgency) where.push("o.urgency = '" + esc(q.urgency) + "'");
if (q.min_budget && !isNaN(parseFloat(q.min_budget)))
  where.push('(o.budget IS NULL OR o.budget >= ' + parseFloat(q.min_budget) + ')');
if (q.q) where.push("(o.summary ILIKE '%" + esc(q.q) + "%' OR o.raw_text ILIKE '%" + esc(q.q) + "%')");
if (q.skills) {
  const s = arr(q.skills).map((x) => "'" + esc(x) + "'");
  if (s.length) where.push('o.skills_required ?| array[' + s.join(',') + ']');
}
if (q.languages) {
  const s = arr(q.languages).map((x) => "'" + esc(x) + "'");
  if (s.length) where.push('o.languages ?| array[' + s.join(',') + ']');
}

let order = 'o.created_at DESC';
if (q.sort === 'budget') order = 'o.budget DESC NULLS LAST, o.created_at DESC';
if (q.sort === 'urgency')
  order = "CASE o.urgency WHEN 'high' THEN 3 WHEN 'medium' THEN 2 ELSE 1 END DESC, o.created_at DESC";

let limit = parseInt(q.limit || '20', 10);
if (isNaN(limit) || limit < 1) limit = 20;
if (limit > 50) limit = 50;
let offset = parseInt(q.offset || '0', 10);
if (isNaN(offset) || offset < 0) offset = 0;

const sql =
  'SELECT o.*, COALESCE(s.status, \'new\') AS user_status, s.note AS user_note ' +
  'FROM orders o ' +
  'LEFT JOIN user_order_status s ON s.order_id = o.id AND s.user_tg_id = ' + uid + ' ' +
  'WHERE ' + where.join(' AND ') + ' ' +
  'ORDER BY ' + order + ' ' +
  'LIMIT ' + limit + ' OFFSET ' + offset + ';';

return [{ json: { sql: sql, limit: limit, offset: offset } }];

